models.demo-tray:
(C)=>{
  const cm=C.cm, T=C.THREE;
  const dark = C.M(C.col, {rough:.55, metal:.15, plastic:true});
  const wood = C.M(C.col2 || 0xC9A575, {wood:'oak', rough:.5, clear:.25});
  /* 托盘面（圆）+ 三条外撇腿：占地 42×42×52cm */
  const R = cm(21), topH = cm(48), th = cm(2.2);
  const top = new T.Mesh(new T.CylinderGeometry(R, R*0.94, th, 40), wood);
  top.position.y = topH; C.g.add(top);
  const lip = new T.Mesh(new T.TorusGeometry(R*0.94, cm(0.9), 8, 40), dark);
  lip.rotation.x = Math.PI/2; lip.position.y = topH + th/2 + cm(0.6); C.g.add(lip);
  for(let i=0;i<3;i++){
    const a = i*Math.PI*2/3 + Math.PI/6;
    const leg = C.cyl(cm(1.1), cm(0.8), topH, dark, Math.cos(a)*R*0.72, 0, Math.sin(a)*R*0.72, 12);
    leg.rotation.z = Math.cos(a)*0.10; leg.rotation.x = -Math.sin(a)*0.10;
  }
  C.g.updateMatrixWorld(true);
  return C.g;
}

models.demo-shelf:
(C)=>{
  const cm=C.cm;
  const steel = C.M(C.col, {rough:.35, metal:.65});
  const board = C.M(0xE7E2D8, {rough:.6, plastic:true});
  const W=cm(20), D=cm(17), H=cm(60), r=cm(1.0);
  /* 四根立管 + 两层板（占地 40×34×60cm） */
  for(const sx of [-1,1]) for(const sz of [-1,1])
    C.cyl(r, r, H, steel, sx*(W-cm(1)), 0, sz*(D-cm(1)), 12);
  C.box(W*2-cm(1.5), cm(1.6), D*2-cm(1.5), board, 0, cm(16), 0);
  C.box(W*2-cm(1.5), cm(1.6), D*2-cm(1.5), board, 0, H-cm(3), 0);
  C.g.updateMatrixWorld(true);
  return C.g;
}
